<template>
  <section><div class="page-heading"><div><p class="eyebrow">الموردون</p><h1>الموردون والمشتريات</h1></div><button class="primary" @click="add">إضافة مورد</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>المورد</th><th>الهاتف</th><th>الدين المستحق</th></tr></thead><tbody><tr v-for="s in suppliers" :key="s._id"><td>{{ s.name }}</td><td>{{ s.phone }}</td><td>{{ money(s.balance) }}</td></tr></tbody></table><p v-if="!suppliers.length" class="empty">لا يوجد موردون بعد</p></div></div></section>
</template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import db from '../services/pouchdb';const suppliers=ref<any[]>([]);const money=(v:number)=>new Intl.NumberFormat('ar-YE',{style:'currency',currency:'YER',maximumFractionDigits:0}).format(v);async function load(){suppliers.value=await db.list<any>('supplier')}async function add(){const name=prompt('اسم المورد');if(!name)return;await db.put({_id:`supplier:${Date.now()}`,type:'supplier',name,phone:prompt('الهاتف')||'',balance:0,created_at:new Date().toISOString()});await load()}onMounted(load)</script>
